'use strict';

// MODULES //

var assertSchema = require( '@data-apis/schema/assert' );
var validateReport = require( '@data-apis/report/validate' );
var filenameTimestamp = require( '@data-apis/record/filename-timestamp' );
var parsePath = require( '@data-apis/record/parse-path' );


// MAIN //

/**
* Validates a stored envelope against its report and path.
*
* @param {Object} envelope - stored record
* @param {string} recordPath - path relative to data
* @param {Object} [options] - validation options
* @returns {Object} validated report metadata
*/
function validateEnvelope( envelope, recordPath, options ) {
	var parsed;
	var validated;
	var retrieved;

	assertSchema( 'stored-record-v1', envelope );
	parsed = parsePath( recordPath );
	validated = validateReport( envelope.report, options || {} );
	if ( parsed.libraryId !== envelope.harvest.library_id || parsed.sourceId !== envelope.harvest.source_id ) {
		throw new Error( 'Stored envelope IDs do not match path ' + recordPath );
	}
	if ( parsed.filenameTimestamp !== filenameTimestamp( validated.timestamp ) ) {
		throw new Error( 'Stored report timestamp does not match path ' + recordPath );
	}
	if ( parsed.reportSha256 !== validated.reportSha256 || envelope.harvest.report_sha256 !== validated.reportSha256 ) {
		throw new Error( 'Stored report hash does not match path/envelope ' + recordPath );
	}
	if ( envelope.harvest.series_schema !== validated.seriesSchema || envelope.harvest.series_key !== validated.seriesKey ) {
		throw new Error( 'Stored series derivation does not match report ' + recordPath );
	}
	retrieved = Date.parse( envelope.harvest.retrieved_at );
	if ( !Number.isFinite( retrieved ) ) {
		throw new Error( 'Invalid retrieval timestamp in ' + recordPath );
	}
	return validated;
}


// EXPORTS //

module.exports = validateEnvelope;
